import{_ as r,c as o,o as a,a7 as s}from"./chunks/framework.DPTpzYjp.js";const e="/ruidu-docs/images/orbitcontrol/user-guide/mgr-maps-page-list.png",i="/ruidu-docs/images/orbitcontrol/user-guide/mgr-maps-dialog-mapping.gif",n="/ruidu-docs/images/orbitcontrol/user-guide/mgr-maps-dialog-delete.png",_=JSON.parse('{"title":"地图管理","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/maps.md","filePath":"orbitcontrol/user-guide/maps.md"}'),d={name:"orbitcontrol/user-guide/maps.md"};function l(g,t,p,c,m,u){return a(),o("div",null,t[0]||(t[0]=[s('<h1 id="地图管理" tabindex="-1">地图管理 <a class="header-anchor" href="#地图管理" aria-label="Permalink to &quot;地图管理&quot;">​</a></h1><p>「地图管理」维护站点的地图：遥控设备<strong>建图</strong>、编辑、重命名、删除、同步到设备。地图是任务规划、标注、路网的基础，参见 <a href="./map.html">地图操作</a>。</p><h2 id="地图列表" tabindex="-1">地图列表 <a class="header-anchor" href="#地图列表" aria-label="Permalink to &quot;地图列表&quot;">​</a></h2><p>选择站点后，地图选择器列出该站点的全部地图（含版本号），底部「<strong>新建地图</strong>」进入建图流程。选中地图后，工具栏提供操作按钮：</p><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td><strong>编辑</strong></td><td>打开图片编辑器，修饰地图底图（裁剪、标注等）</td></tr><tr><td><strong>更名</strong></td><td>修改地图名称</td></tr><tr><td><strong>重建</strong></td><td>用现有地图名称重新建图（旧图数据保留）</td></tr><tr><td><strong>删除</strong></td><td>从平台删除该地图</td></tr><tr><td><strong>同步</strong></td><td>将站点地图下发到站点内所有设备</td></tr></tbody></table><p><img src="'+e+'" alt=""></p><h2 id="新建地图-遥控建图" tabindex="-1">新建地图（遥控建图） <a class="header-anchor" href="#新建地图-遥控建图" aria-label="Permalink to &quot;新建地图（遥控建图）&quot;">​</a></h2><p>建图通过遥控设备实地走一遍完成，分四步：</p><p><img src="'+i+'" alt=""></p><ol><li><strong>选择设备</strong>：选择站点内用于建图的在线设备</li><li><strong>确认切换建图模式</strong>：设备将切换至建图模式，此操作会<strong>中断设备当前正在执行的任务</strong>，切换过程约需 5-6 秒</li><li><strong>切换中</strong>：等待设备完成模式切换</li><li><strong>建图</strong>：通过 FPV 面板和摇杆遥控设备，<strong>缓慢移动</strong>遍历场地，页面实时显示建图进度帧；完成后点击「保存」，输入地图名称</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>建图会中断设备当前任务，请选择设备空闲时进行。</p></div><h2 id="删除地图" tabindex="-1">删除地图 <a class="header-anchor" href="#删除地图" aria-label="Permalink to &quot;删除地图&quot;">​</a></h2><p><img src="'+n+'" alt="" class="w-1/2"></p><p>删除地图会：</p><ul><li>通知站点内所有设备<strong>清理本地地图文件</strong></li><li>从平台删除该地图（版本数据保留用于审计）</li></ul><h2 id="同步地图" tabindex="-1">同步地图 <a class="header-anchor" href="#同步地图" aria-label="Permalink to &quot;同步地图&quot;">​</a></h2><p>地图更新（建图、编辑）后，点击「同步」将站点最新地图下发到站点内所有设备，保证设备本地地图与平台一致。</p>',17)]))}const b=r(d,[["render",l]]);export{_ as __pageData,b as default};
